        /// <summary>世界座標 → 地板 uv。</summary>
        public static Vector2 ToUV(float x, float y)
        {
            float dx = x - IsoX, dy = IsoY - y;
            return new Vector2(dy + dx * 0.5f, dy - dx * 0.5f);
